const chebyshevDistance = ([x1, y1]: Cell, [x2, y2]: Cell): number =>
  Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2));

const isNeighbor = (cell: Cell, otherCell: Cell): boolean =>
  chebyshevDistance(cell, otherCell) === 1;
